FILES = {
 "backend/app/feature_engineering/common.py": "\"\"\"Shared utilities for CIRA Chapter 5 feature engineering.\n\nNo ground-truth data is imported here.  The feature path is deliberately\nlabel-blind and operates only on processed CERT events/context.\n\"\"\"\nfrom __future__ import annotations\n\nimport json\nimport os\nimport time\nfrom pathlib import Path\nfrom typing import Iterable\n\nimport numpy as np\nimport pandas as pd\n\nDATE_FORMAT = \"%m/%d/%Y %H:%M:%S\"\nOFF_HOURS_START = 7\nOFF_HOURS_END = 19  # 19:00 is outside the 07:00-18:59 work window.\nBASELINE_WINDOW = 30\nBASELINE_MIN_PERIODS = 7\n\n# CERT r4.2 has exactly these six file extensions.  These are structural\n# categories, not ground-truth-derived \"sensitive\" lists.\nFILE_EXTENSIONS = (\"doc\", \"pdf\", \"txt\", \"jpg\", \"zip\", \"exe\")\n\n\ndef as_user_day_frame(df: pd.DataFrame) -> pd.DataFrame:\n    \"\"\"Return a stable, typed user/day key frame.\"\"\"\n    out = df.copy()\n    out[\"user_id\"] = out[\"user_id\"].astype(\"string\")\n    out[\"date\"] = pd.to_datetime(out[\"date\"], errors=\"raise\").dt.normalize()\n    return out\n\n\ndef day_and_hour_from_cert_date(series: pd.Series) -> tuple[pd.Series, pd.Series]:\n    \"\"\"Use CERT string slicing for hot paths; parse only when needed.\"\"\"\n    s = series.astype(\"string\")\n    day = pd.to_datetime(s.str.slice(0, 10), format=\"%m/%d/%Y\", errors=\"raise\")\n    hour = pd.to_numeric(s.str.slice(11, 13), errors=\"raise\").astype(\"int8\")\n    return day, hour\n\n\ndef normalize_user(series: pd.Series) -> pd.Series:\n    return series.astype(\"string\").str.strip().str.casefold()\n\n\ndef normalize_text(series: pd.Series) -> pd.Series:\n    return series.astype(\"string\").fillna(\"\").str.strip().str.casefold()\n\n\ndef off_hours(hour: pd.Series) -> pd.Series:\n    return ((hour < OFF_HOURS_START) | (hour >= OFF_HOURS_END)).astype(\"int8\")\n\n\ndef ratio(num: pd.Series, den: pd.Series) -> pd.Series:\n    return (num.astype(\"float32\") / den.replace(0, np.nan)).astype(\"float32\")\n\n\ndef to_float32(df: pd.DataFrame, exclude: Iterable[str] = (\"user_id\", \"date\")) -> pd.DataFrame:\n    excluded = set(exclude)\n    for col in df.columns:\n        if col not in excluded and pd.api.types.is_numeric_dtype(df[col]):\n            df[col] = df[col].astype(\"float32\")\n    return df\n\n\ndef atomic_to_parquet(df: pd.DataFrame, path: Path) -> None:\n    path.parent.mkdir(parents=True, exist_ok=True)\n    tmp = path.with_suffix(path.suffix + \".tmp\")\n    df.to_parquet(tmp, engine=\"pyarrow\", compression=\"zstd\", index=False)\n    os.replace(tmp, path)\n\n\ndef read_parquet_tree(root: Path, columns: list[str] | None = None) -> Iterable[pd.DataFrame]:\n    \"\"\"Yield parquet parts one at a time; never concatenate raw-scale data.\"\"\"\n    for path in sorted(root.rglob(\"*.parquet\")):\n        yield pd.read_parquet(path, columns=columns, engine=\"pyarrow\")\n\n\ndef parse_host(url: pd.Series) -> pd.Series:\n    # CERT r4.2 uses http URLs.  Avoid urllib object creation for 28M rows.\n    host = (\n        url.astype(\"string\")\n        .str.extract(r\"^[A-Za-z]+://([^/:?#]+)\", expand=False)\n        .fillna(\"\")\n        .str.casefold()\n        .str.rstrip(\".\")\n    )\n    return host.astype(\"string\")\n\n\ndef extension(series: pd.Series) -> pd.Series:\n    return (\n        series.astype(\"string\")\n        .str.casefold()\n        .str.extract(r\"\\.([a-z0-9]{1,8})$\", expand=False)\n        .fillna(\"other\")\n    )\n\n\ndef memory_rss_mb() -> float:\n    \"\"\"Peak resident memory of this process so far, in MiB (HCEA R8).\n\n    Windows: PeakWorkingSetSize. Linux/macOS: ru_maxrss. Both are process\n    high-water marks, so a value logged at the end of a run is the true peak,\n    not a snapshot taken after large frames were freed.\n    \"\"\"\n    if os.name == \"nt\":\n        import ctypes\n        from ctypes import wintypes\n\n        class PROCESS_MEMORY_COUNTERS(ctypes.Structure):\n            _fields_ = [\n                (\"cb\", wintypes.DWORD),\n                (\"PageFaultCount\", wintypes.DWORD),\n                (\"PeakWorkingSetSize\", ctypes.c_size_t),\n                (\"WorkingSetSize\", ctypes.c_size_t),\n                (\"QuotaPeakPagedPoolUsage\", ctypes.c_size_t),\n                (\"QuotaPagedPoolUsage\", ctypes.c_size_t),\n                (\"QuotaPeakNonPagedPoolUsage\", ctypes.c_size_t),\n                (\"QuotaNonPagedPoolUsage\", ctypes.c_size_t),\n                (\"PagefileUsage\", ctypes.c_size_t),\n                (\"PeakPagefileUsage\", ctypes.c_size_t),\n            ]\n\n        counters = PROCESS_MEMORY_COUNTERS()\n        counters.cb = ctypes.sizeof(PROCESS_MEMORY_COUNTERS)\n\n        handle = ctypes.windll.kernel32.GetCurrentProcess()\n        get_info = ctypes.windll.psapi.GetProcessMemoryInfo\n\n        get_info.argtypes = [\n            wintypes.HANDLE,\n            ctypes.POINTER(PROCESS_MEMORY_COUNTERS),\n            wintypes.DWORD,\n        ]\n        get_info.restype = wintypes.BOOL\n\n        ok = get_info(\n            handle,\n            ctypes.byref(counters),\n            counters.cb,\n        )\n\n        if ok:\n            return counters.PeakWorkingSetSize / (1024 ** 2)\n\n        return float(\"nan\")\n\n    import resource\n\n    value = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss\n\n    if os.uname().sysname == \"Linux\":\n        return float(value / 1024)\n\n    return float(value / (1024 ** 2))\n\ndef timed_stage(name: str, runlog: Path, **extra):\n    return _StageTimer(name, runlog, extra)\n\n\nclass _StageTimer:\n    def __init__(self, name: str, runlog: Path, extra: dict | None = None):\n        self.name = name\n        self.runlog = runlog\n        self.extra = dict(extra or {})\n        self.started = 0.0\n        self.peak = 0.0\n\n    def __enter__(self):\n        self.started = time.perf_counter()\n        self.peak = memory_rss_mb()\n        return self\n\n    def __exit__(self, exc_type, exc, tb):\n        self.peak = max(self.peak, memory_rss_mb())\n        record = {\n            \"stage\": self.name,\n            \"wall_seconds\": round(time.perf_counter() - self.started, 3),\n            \"peak_rss_mb\": round(self.peak, 2),\n            \"status\": \"failed\" if exc else \"completed\",\n            **self.extra,\n        }\n        self.runlog.parent.mkdir(parents=True, exist_ok=True)\n        with self.runlog.open(\"a\", encoding=\"utf-8\") as fh:\n            fh.write(json.dumps(record) + \"\\n\")\n        return False\n\n\ndef ensure_pyarrow() -> None:\n    try:\n        import pyarrow  # noqa: F401\n    except ImportError as exc:\n        raise RuntimeError(\n            \"Chapter 5 requires pyarrow for Parquet I/O. Add pyarrow to backend/requirements.txt.\"\n        ) from exc\n\n\n# ---------------------------------------------------------------------------\n# Chunk-safe combination of per-part aggregates (HCEA \u00a75.3)\n# ---------------------------------------------------------------------------\n# Per-part aggregates are combined with a per-column rule.  Only additive\n# columns may be summed.  Distinct counts are NEVER combined here: they are\n# recomputed exactly from deduplicated (user, day, item) triples.\n\ndef combine_rule(column: str) -> str:\n    \"\"\"Return the correct cross-part reducer for an aggregate column.\"\"\"\n    if column.endswith((\"_first_hour\",)) or column == \"first_auth_hour\":\n        return \"min\"\n    if column.endswith((\"_last_hour\",)) or column == \"last_auth_hour\":\n        return \"max\"\n    if column.endswith(\"_flag\"):\n        return \"max\"\n    return \"sum\"\n\n\ndef is_distinct_column(column: str) -> bool:\n    return \"distinct\" in column\n\n\ndef is_ratio_column(column: str) -> bool:\n    return column.endswith((\"_ratio\", \"_avg\"))\n\n\n# ---------------------------------------------------------------------------\n# Host classification (vectorised over unique hosts, not 28M rows)\n# ---------------------------------------------------------------------------\n\ndef host_matches(host: str, suffixes: tuple[str, ...]) -> bool:\n    return any(host == s or host.endswith(\".\" + s) for s in suffixes)\n\n\ndef categorize_hosts(\n    host: pd.Series,\n    categories: dict[str, tuple[str, ...]],\n) -> pd.DataFrame:\n    \"\"\"Return one int8 indicator column per category, aligned to ``host``.\"\"\"\n    codes, uniques = pd.factorize(host.astype(\"string\").fillna(\"\"), sort=False)\n    out = {}\n    for name, suffixes in categories.items():\n        lookup = np.fromiter(\n            (host_matches(str(h), suffixes) for h in uniques),\n            dtype=np.int8,\n            count=len(uniques),\n        )\n        values = lookup[codes] if len(uniques) else np.zeros(len(host), dtype=np.int8)\n        out[name] = values\n    return pd.DataFrame(out, index=host.index)\n\n\n# ---------------------------------------------------------------------------\n# Evidence trail (HCEA R8)\n# ---------------------------------------------------------------------------\n\ndef repo_root() -> Path:\n    # backend/app/feature_engineering/common.py -> repo root\n    return Path(__file__).resolve().parents[3]\n\n\ndef append_experiment_runlog(record: dict) -> Path:\n    \"\"\"Append one JSON line to experiments/runlog.jsonl in the repository.\"\"\"\n    path = Path(os.getenv(\"CIRA_RUNLOG\", str(repo_root() / \"experiments\" / \"runlog.jsonl\")))\n    path.parent.mkdir(parents=True, exist_ok=True)\n    with path.open(\"a\", encoding=\"utf-8\") as fh:\n        fh.write(json.dumps(record, default=str) + \"\\n\")\n    return path\n",
 "backend/tests/unit/test_feature_units_ch5.py": "\"\"\"Unit tests for Chapter 5 sub-domains that previously had none.\"\"\"\nimport numpy as np\nimport pandas as pd\n\nfrom app.feature_engineering import application, file_activity, temporal\nfrom app.feature_engineering.common import categorize_hosts, combine_rule\nfrom app.feature_engineering.network import aggregate as http_aggregate\nfrom app.feature_engineering.peer_group import add_peer_features, leave_one_out_median\n\n\ndef _rows(**extra):\n    base = {\n        \"event_id\": [\"1\", \"2\", \"3\"],\n        \"date_day\": pd.to_datetime([\"2010-01-04\"] * 3),\n        \"hour\": [8, 20, 9],\n        \"weekday\": [0, 0, 0],\n        \"user_id\": [\"u1\"] * 3,\n        \"device_id\": [\"pc1\", \"pc2\", \"pc1\"],\n    }\n    base.update(extra)\n    return pd.DataFrame(base)\n\n\ndef test_file_activity_extension_counts_and_off_hours():\n    out = file_activity.aggregate(_rows(file_extension=[\"zip\", \"exe\", \"weird\"]))\n    row = out.iloc[0]\n    assert row.file_event_count == 3\n    assert row.file_zip_count == 1 and row.file_exe_count == 1\n    assert row.file_other_ext_count == 1\n    assert row.file_archive_or_executable_count == 2\n    assert row.file_off_hours_events == 1\n    assert row.file_distinct_pcs == 2\n\n\ndef test_application_family_emits_no_fabricated_columns():\n    out = application.aggregate(pd.DataFrame())\n    assert list(out.columns) == [\"user_id\", \"date\"]\n    assert out.empty\n\n\ndef test_temporal_nulls_absence_and_rolls_without_current_day():\n    df = pd.DataFrame({\n        \"user_id\": [\"u1\"] * 4,\n        \"date\": pd.date_range(\"2010-01-01\", periods=4),\n        \"first_auth_hour\": [8.0, np.nan, 22.0, 9.0],\n        \"last_auth_hour\": [17.0, np.nan, 23.0, 9.0],\n        \"auth_event_count\": [2, 0, 2, 1],\n        \"http_request_count\": [5, 0, 0, 3],\n    })\n    out = temporal.add_temporal(df)\n    assert out[\"first_auth_off_hours\"].tolist()[0] == 0\n    assert np.isnan(out[\"first_auth_off_hours\"].tolist()[1])\n    assert out[\"first_auth_off_hours\"].tolist()[2] == 1\n    assert out[\"total_event_count\"].tolist() == [7, 0, 2, 4]\n    assert out[\"is_active_day\"].tolist() == [1, 0, 1, 1]\n    rolled = out[\"rolling_7d_event_count\"].tolist()\n    assert np.isnan(rolled[0])                   # no prior day\n    assert rolled[1] == 7 and rolled[3] == 9     # current day excluded\n    assert out[\"auth_active_span_hours\"].tolist()[0] == 9\n\n\ndef test_combine_rules():\n    assert combine_rule(\"usb_first_hour\") == \"min\"\n    assert combine_rule(\"first_auth_hour\") == \"min\"\n    assert combine_rule(\"usb_last_hour\") == \"max\"\n    assert combine_rule(\"http_x_flag\") == \"max\"\n    assert combine_rule(\"login_count\") == \"sum\"\n\n\ndef test_host_categories_match_exact_or_subdomain_only():\n    hosts = pd.Series([\"drive.google.com\", \"x.drive.google.com\", \"google.com\", \"notdropbox.com\", \"dropbox.com\"])\n    flags = categorize_hosts(hosts, {\"cloud\": (\"drive.google.com\", \"dropbox.com\")})\n    assert flags[\"cloud\"].tolist() == [1, 1, 0, 0, 1]\n\n\ndef test_http_category_counts_are_additive_columns():\n    df = _rows(host=[\"dropbox.com\", \"cnn.com\", \"dropbox.com\"])\n    out = http_aggregate(df, {\"cloud_storage\": (\"dropbox.com\",)})\n    assert out.iloc[0].http_cloud_storage_count == 2\n    assert out.iloc[0].http_request_count == 3\n\n\ndef test_leave_one_out_median_matches_brute_force():\n    rng = np.random.default_rng(0)\n    for _ in range(50):\n        n = int(rng.integers(1, 25))\n        v = pd.Series(rng.integers(0, 5, n).astype(float))\n        g = pd.Series(rng.integers(0, 3, n))\n        got = leave_one_out_median(v, g)\n        for i in range(n):\n            peers = v[(g == g[i]) & (v.index != i)]\n            exp = peers.median() if len(peers) else np.nan\n            assert (np.isnan(exp) and np.isnan(got[i])) or np.isclose(exp, got[i])\n\n\ndef test_peer_group_compares_same_day_not_whole_month():\n    # u2's huge value on Jan 20 must not affect u1's Jan 10 peer median.\n    df = pd.DataFrame({\n        \"user_id\": [\"u1\", \"u2\", \"u1\", \"u2\"],\n        \"date\": pd.to_datetime([\"2010-01-10\", \"2010-01-10\", \"2010-01-20\", \"2010-01-20\"]),\n        \"login_count\": [1.0, 2.0, 1.0, 999.0],\n    })\n    ldap = pd.DataFrame({\n        \"user_id\": [\"u1\", \"u2\"], \"department\": [\"d\", \"d\"], \"functional_unit\": [\"f\", \"f\"],\n        \"snapshot_month\": pd.to_datetime([\"2010-01-01\", \"2010-01-01\"]),\n    })\n    out, _ = add_peer_features(df, ldap)\n    jan10_u1 = out[(out.user_id == \"u1\") & (out.date == \"2010-01-10\")].iloc[0]\n    assert jan10_u1.peer_median_login_count == 2.0\n\n\ndef test_peer_group_separates_same_department_name_in_other_functional_unit():\n    df = pd.DataFrame({\n        \"user_id\": [\"u1\", \"u2\"], \"date\": pd.to_datetime([\"2010-01-10\"] * 2), \"login_count\": [1.0, 5.0],\n    })\n    ldap = pd.DataFrame({\n        \"user_id\": [\"u1\", \"u2\"], \"department\": [\"1 - Sales\", \"1 - Sales\"], \"functional_unit\": [\"A\", \"B\"],\n        \"snapshot_month\": pd.to_datetime([\"2010-01-01\"] * 2),\n    })\n    out, _ = add_peer_features(df, ldap)\n    assert out[\"peer_median_login_count\"].isna().all()\n\n\ndef test_feature_package_never_imports_ground_truth():\n    import ast\n    from pathlib import Path\n\n    import app.feature_engineering as fe\n\n    for path in Path(fe.__file__).parent.glob(\"*.py\"):\n        tree = ast.parse(path.read_text(encoding=\"utf-8\"))\n        for node in ast.walk(tree):\n            if isinstance(node, ast.ImportFrom):\n                assert \"ground_truth\" not in (node.module or \"\"), path.name\n            if isinstance(node, ast.Import):\n                assert all(\"ground_truth\" not in a.name for a in node.names), path.name\n\n\ndef test_memory_rss_is_a_high_water_mark():\n    import numpy as np\n    from app.feature_engineering.common import memory_rss_mb\n\n    before = memory_rss_mb()\n    big = np.ones(40 * 1024 * 1024 // 8)   # ~40 MiB\n    during = memory_rss_mb()\n    del big\n    after = memory_rss_mb()\n    assert during >= before\n    assert after >= during - 1             # peak must not drop after freeing\n",
 "docs/audits/chapter_1_5_audit.md": "# Chapter 1-5 audit (24 September 2026)\n\nScope: repository state at commit `d3bb41f` checked against the\nImplementation Bible (Chapters 1-5) and HCEA v1.0 (\u00a72 standing rules, \u00a73-5).\nEvidence: code reading, the existing test suite, and an end-to-end run of the\nChapter 5 pipeline on a synthetic CERT-shaped tree with small chunk sizes,\ncompared column by column against brute-force values computed from the raw\nCSVs.\n\n## Result before fixes\n\nChapters 1-4: pass. Chapter 5: not accepted. Existing tests passed (58/58)\nbut only exercised single-chunk inputs, which is where the defects hide.\n\n## Defects found and fixed\n\n| # | Defect | Evidence | Fix |\n|---|---|---|---|\n| 1 | `usb_distinct_pcs`, `file_distinct_pcs` summed across Parquet parts (the HCEA \u00a75.3 chunk-safety bug) | 213 of 2,563 user-days wrong on synthetic run; max 5 vs true max 3 | Exact counts from globally deduplicated (user, day, item) triples |\n| 2 | `usb_first_hour` / `usb_last_hour` summed across parts | Values up to 42 (not a clock hour) | Per-column combine rules: min/max for hours, max for flags, sum only for additive columns |\n| 3 | Inactive days treated as a midnight logon: `first_auth_hour` filled with 0, so `first_auth_off_hours` = 1 on every no-login day | 1,423 of 1,423 idle days flagged off-hours | Hour columns stay null; off-hours flags null when there was no logon |\n| 4 | Ratios zero-filled on days with no denominator; schema recorded \"zero\" | `off_hours_login_ratio` = 0 on idle days | Ratios null (undefined); schema null_policy states this |\n| 5 | Peer median pooled over the whole month (includes peers' future days) and ran a per-row Python loop | ~3-4 ms/row measured, tens of minutes at full scale | Same-day peer groups (functional_unit + department), exact leave-one-out median, vectorised: 450k rows in 0.15 s, verified against brute force |\n| 6 | No HTTP host-class features; `DEFAULT_HOST_CATEGORIES` empty (HCEA \u00a75.2 requires a committed expert list) | No host-class columns | `network_domains.py` draft list (job search, cloud storage, leak/paste, hacking tools) + label-blind `scripts/http_host_inventory.py` for review |\n| 7 | Stage 0 CLI crashed (`run_stage0()` missing `profile`) | TypeError on the documented command | CLI fixed, profile/env aware |\n| 8 | Stage 0 resumable only per whole domain, not per part (HCEA R7, \u00a75.2) | A crash mid-http restarts http from zero | Per-chunk `.done` markers; config fingerprint invalidates stale outputs; tested by a simulated kill |\n| 9 | One malformed timestamp aborted the run (`errors=\"raise\"`); no rejected sink in Stage 0 (Bible Ch4 rule) | Code | Malformed rows go to `processed/rejected/` with a reason code |\n| 10 | Dev profile window Jan-Apr 2010 precedes all r4.2 insider activity (earliest answer-file events seen: June 2010) | Answer-file dates | Dev window Jun-Aug 2010; dev insiders chosen from those active in the window; fails loudly if fewer than 10 |\n| 11 | No evaluation label tables (`labels/insider_user_days.parquet`, HCEA \u00a73.4) | Missing | `build_insider_label_tables()` in the ground-truth module (event-level answer files) + `scripts/build_labels.py`; feature package statically barred from importing it |\n| 12 | Email size/attachments zero-filled when missing | Code | Kept null |\n| 13 | HCEA \u00a717 variables absent from config and `.env.example`; `.env` path depended on CWD | Code | Added; path resolved from the repo root |\n| 14 | No thread caps (R6), runlog lacked rows/config hash (R8) | Code | `app/core/runtime.py`; `experiments/runlog.jsonl` summary per run |\n| 15 | Four duplicated `* copy.py` test files; empty README; no tests for file_activity, temporal, application, stage0, pipeline | Repo | Removed / written / added (80 tests pass) |\n\nAdded features along the way: `email_distinct_external_domains`, temporal\nrolling 7-day activity and active-day counts, `auth_active_span_hours`,\n`total_event_count`, static psychometric (OCEAN) context columns.\n\n## Documented deviations (not silent)\n\n- Stage 0 applies the Chapter 4 policy vectorised per chunk rather than\n  calling the per-event Pydantic path, which would be too slow at 3.2x10^7\n  rows. Duplicate ids are rejected within a chunk; CERT ids are unique per\n  domain, so a multi-GB global id set is not built.\n- CERT r4.2 has no failed logins, source IPs, byte counts, file\n  create/modify/delete, or application/process logs. Those Architecture \u00a710\n  sub-features are omitted, not fabricated; `application.py` emits no columns.\n- The feature matrix contains nulls by design. Chapter 6 must impute with a\n  policy fitted on the training split only.\n\n## Still required on the real dataset (cannot be verified in review)\n\n1. Review `network_domains.py` against `scripts/http_host_inventory.py`\n   output, by host category only, never by who visited a host.\n2. Run `scripts/build_labels.py`; confirm 7,323 events and 70 users.\n3. Run the pipeline at dev, then mid; record wall-clock and peak RSS.\n   HCEA \u00a75.5 targets: dev under ~2 minutes, full-pipeline peak RSS under 12 GB.\n4. Kill the http stage mid-run once at mid and confirm it resumes (HCEA \u00a75.5).\n5. Save `experiments/dataset_inventory.txt` (HCEA \u00a73.2) and commit it.\n\n## Follow-up review (commit 9f69389, real-data runs)\n\nFixes applied exactly as tested; 80/80 tests pass on the committed code.\n`experiments/runlog.jsonl` shows:\n\n| Profile | Users | Events in | Rejected | User-days out | Features | Wall-clock |\n|---|---|---|---|---|---|---|\n| dev | 49 | 254,850 | 0 | 4,258 | 112 | 267 s |\n| mid | 250 | 7,180,298 | 0 | 106,914 | 112 | 277 s (2 s cached re-run) |\n\nDefect 16 found in this review: on Windows `memory_rss_mb()` returned\n`WorkingSetSize` (current memory), and the summary is logged at the end of a\nrun, so the logged 331 MB / 550 MB are end-of-run snapshots, not peaks.\nFixed to `PeakWorkingSetSize`; the HCEA \u00a75.5 peak-RSS item must be re-measured.\n\nNotes:\n- dev selects 50 users but only 49 have activity in Jun-Aug 2010; one user\n  contributes no rows. Acceptable for a dev profile; worth knowing.\n- dev takes ~4.5 min, above the ~2 min HCEA target, because Stage 0 must scan\n  every raw CSV once regardless of profile size. Cached re-runs are seconds.\n- The 2 s mid re-run proves stage caching, not crash-resume. The kill-and-resume\n  check (HCEA \u00a75.5) is still to be demonstrated on real data.\n",
 "scripts/build_labels.py": "\"\"\"Build CERT r4.2 evaluation label tables (evaluation-only, HCEA \u00a73.4).\n\nWrites <CERT_PROCESSED_DIR>/labels/insider_events.parquet and\ninsider_user_days.parquet from the event-level answer files in\n<CERT_GROUND_TRUTH_DIR>/r4.2-{1,2,3}/.  The feature pipeline never reads this\ntree; labels are joined to features only inside the Chapter 6+ evaluation code.\n\nUsage (from the repo root, with .env loaded or flags given):\n    python scripts/build_labels.py\n    python scripts/build_labels.py --ground-truth-dir D:/CIRA_dataset/datasets/ground_truth/cert_r4.2 \\\n                                   --processed-dir   D:/CIRA_dataset/datasets/processed\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport json\nimport os\nimport sys\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parents[1] / \"backend\"))\n\nfrom app.feature_engineering.common import append_experiment_runlog  # noqa: E402\nfrom app.ingestion.ground_truth import build_insider_label_tables  # noqa: E402\n\nEXPECTED_EVENTS = 7_323   # Bible Chapter 3 / HCEA \u00a73.2 (released r4.2 ground truth)\nEXPECTED_USERS = 70\n\n\ndef main() -> None:\n    p = argparse.ArgumentParser()\n    p.add_argument(\"--ground-truth-dir\", default=os.getenv(\"CERT_GROUND_TRUTH_DIR\"), required=os.getenv(\"CERT_GROUND_TRUTH_DIR\") is None)\n    p.add_argument(\"--processed-dir\", default=os.getenv(\"CERT_PROCESSED_DIR\"), required=os.getenv(\"CERT_PROCESSED_DIR\") is None)\n    args = p.parse_args()\n    summary = build_insider_label_tables(args.ground_truth_dir, args.processed_dir)\n    summary[\"expected_events\"] = EXPECTED_EVENTS\n    summary[\"expected_users\"] = EXPECTED_USERS\n    summary[\"matches_published_counts\"] = (\n        summary[\"malicious_events\"] == EXPECTED_EVENTS and summary[\"insider_users\"] == EXPECTED_USERS\n    )\n    print(json.dumps(summary, indent=2))\n    append_experiment_runlog({\"stage\": \"build_labels\", **{k: v for k, v in summary.items() if k != \"output_dir\"}})\n    if not summary[\"matches_published_counts\"]:\n        print(\"WARNING: counts differ from the published r4.2 figures; investigate before Chapter 6.\", file=sys.stderr)\n\n\nif __name__ == \"__main__\":\n    main()\n"
}
DELETE = [
 "apply_ch5_fixes.py",
 "ch5_audit_fixes.patch"
]
EXPECTED_ORIGINAL_SHA256 = {
 "apply_ch5_fixes.py": "55320dd2d3ce05ac6e48f50beae287ec57d7c8fc0281345d1e948fad318a3d48",
 "backend/app/feature_engineering/common.py": "6e5f7fca97d0b4964bdbe77ed947778bf13efdc5e078fd2f73a0255bf5633a70",
 "backend/tests/unit/test_feature_units_ch5.py": "5eb5aec6d45159d2e473bdc6cfd3a004c0be9ba470db8492e7f1336e47738e04",
 "ch5_audit_fixes.patch": "34884a800a8c559ab52798d06c054be9367b098837a41dbec2cfdde6bcba937d",
 "docs/audits/chapter_1_5_audit.md": "2b75fb91519b6400ef1be36bba0dff202d9d0a1a00b764e85c74e8b3450c4d0d",
 "scripts/build_labels.py": "8f70c384db69118523b6bb03aa29927bf308942262dd85eeca9ed4cd9ac11a67"
}


def sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes().replace(b"\r\n", b"\n").rstrip(b"\r")).hexdigest()


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--dry-run", action="store_true")
    ap.add_argument("--force", action="store_true", help="overwrite files that have local edits")
    ap.add_argument("--run-tests", action="store_true")
    args = ap.parse_args()

    root = Path.cwd()
    if not (root / "backend" / "app" / "feature_engineering" / "pipeline.py").exists():
        print("Run this from the cira-insider-risk repository root.", file=sys.stderr)
        return 2

    drift = []
    for rel, digest in EXPECTED_ORIGINAL_SHA256.items():
        p = root / rel
        if p.exists() and sha(p) != digest:
            drift.append(rel)
    already = [rel for rel, text in FILES.items() if (root / rel).exists() and (root / rel).read_text(encoding="utf-8").replace("\r\n", "\n") == text]
    if drift and not args.force:
        unexpected = [d for d in drift if d not in already]
        if unexpected:
            print("These files differ from commit " + BASE_COMMIT + " (local edits?):", file=sys.stderr)
            for d in unexpected:
                print("  " + d, file=sys.stderr)
            print("Commit or stash them first, or re-run with --force (originals are still backed up).", file=sys.stderr)
            return 3

    stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    backup = root / ".ch5_fix_backup" / stamp
    written = deleted = unchanged = 0

    for rel, text in FILES.items():
        target = root / rel
        if rel in already:
            unchanged += 1
            continue
        print(("would write " if args.dry_run else "write  ") + rel)
        if args.dry_run:
            continue
        if target.exists():
            (backup / rel).parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(target, backup / rel)
        target.parent.mkdir(parents=True, exist_ok=True)
        with open(target, "w", encoding="utf-8", newline="\n") as fh:
            fh.write(text)
        written += 1

    for rel in DELETE:
        target = root / rel
        if not target.exists():
            continue
        print(("would delete " if args.dry_run else "delete ") + rel)
        if args.dry_run:
            continue
        (backup / rel).parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(target, backup / rel)
        target.unlink()
        deleted += 1

    if args.dry_run:
        print("\nDry run only. Nothing changed.")
        return 0

    print(f"\n{written} file(s) written, {deleted} deleted, {unchanged} already up to date.")
    if written or deleted:
        print(f"Originals backed up under {backup.relative_to(root)}")

    if args.run_tests:
        print("\nRunning pytest ...")
        code = subprocess.call([sys.executable, "-m", "pytest", "-q"], cwd=root)
        if code != 0:
            print("pytest failed. Check that backend/requirements.txt is installed (pyarrow included).", file=sys.stderr)
            return code

    print("""
Next: re-run the mid profile (logs true peak RSS), run scripts/build_labels.py,
review network_domains.py, then git add -A && git commit.
""")
    return 0


if __name__ == "__main__":
    sys.exit(main())
